// Petit module d'exemple : sa version minifiée sert aux tests de symbolisation.
export function calculerTotal(articles) {
  let total = 0;
  for (const article of articles) {
    total += prixDe(article) * article.quantite;
  }
  return total;
}

function prixDe(article) {
  if (!article.prix) {
    throw new TypeError('Prix manquant pour ' + article.nom);
  }
  return article.prix.montant;
}

export function payer(panier) {
  const total = calculerTotal(panier.articles);
  return { total, devise: 'EUR' };
}
